            if (settle >= 10) {
              phase = 'cross';
              settle = 0;
            }
          }

          if (phase === 'cross') {
            target = { x: gate.x + 0.35, y: gate.y, z: gate.z };
            // 6. Predictive cross abort
            const dxGate = gate.x - p.x;
            if (dxGate > 0.035) {
              const tCross = clamp(dxGate / Math.max(vf.x, 0.35), 0.04, 0.28);
              const ayLat = dFast.y - dSlow.y;
              const azLat = dFast.z - dSlow.z;
              const pyPred = p.y + vf.y * tCross + 0.3 * ayLat * tCross * tCross;
              const pzPred = p.z + vf.z * tCross + 0.3 * azLat * tCross * tCross;
