              const pzNow = p.z + vf.z * 0.06;

              const unsafeZ = Math.abs(p.z - gate.z) > 0.082 || Math.abs(pzPred - gate.z) > 0.092 || Math.abs(pzNow - gate.z) > 0.086;
              const unsafeY = Math.abs(p.y - gate.y) > 0.15 || Math.abs(pyPred - gate.y) > 0.17 || Math.abs(pyNow - gate.y) > 0.16;
              const canStop = dxGate > Math.max(0.04, (vf.x * vf.x) / 11.0);

              if ((unsafeZ || unsafeY) && canStop) {
                phase = 'align';
                settle = 0;
                target = { x: alignX, y: gate.y, z: gate.z };
                ref.x = Math.min(p.x - 0.12, alignX);
              }
            } else if (dxGate < -0.04) {
              // Missed gate outside frame: return to align
              phase = 'align';
              settle = 0;
              target = { x: alignX, y: gate.y, z: gate.z };
            }
          }
        } else {
          // 7. Ramp pad descent
          const pad = obs.pad.centre;
          const distXZ = Math.hypot(pad.x - p.x, pad.z - p.z);
          const speedXZ = Math.hypot(vf.x, vf.z);
          if (distXZ > 0.35) {
            padY = clamp(0.25 + 0.65 * distXZ, 0.40, 0.75);
          } else if (distXZ < 0.22) {
            if (padY > 0.20) {
              padY = Math.max(0.20, padY - 0.55 * dt);
            } else if (distXZ < 0.115 && speedXZ < 0.28) {
              padY = Math.max(0.015, padY - 0.24 * dt);
            } else if (distXZ > 0.135 && p.y > 0.088) {
              padY = Math.max(padY, 0.16);
            }
          }
          target = { x: pad.x, y: padY, z: pad.z };
        }
      }

      // 4. Smooth ref filter
      const alphaRef = phase === 'cross' ? 0.14 : 0.10;
      ref.x += alphaRef * (target.x - ref.x);
      ref.y += alphaRef * (target.y - ref.y);
      ref.z += alphaRef * (target.z - ref.z);

      // 3. Yaw + local pos integrals
      const ex = ref.x - p.x, ey = ref.y - p.y, ez = ref.z - p.z;
      const tdx = target.x - p.x, tdy = target.y - p.y, tdz = target.z - p.z;

      if (Math.abs(tdx) < 0.32) intPos.x = clamp(intPos.x + tdx * dt, -0.45, 0.45);
      else intPos.x *= 0.98;

      if (Math.abs(tdy) < 0.40 && p.y > 0.08) intPos.y = clamp(intPos.y + tdy * dt, -0.6, 0.6);
      else if (p.y <= 0.08) intPos.y *= 0.95;

      if (Math.abs(tdz) < 0.32) intPos.z = clamp(intPos.z + tdz * dt, -0.45, 0.45);
      else intPos.z *= 0.98;

      if (p.y > 0.08) intYaw = clamp(intYaw + att.yaw * dt, -0.5, 0.5);

      // Outer loop control with disturbance feedforward
      const dEstX = dSlow.x + 0.85 * (dFast.x - dSlow.x);
      const dEstY = dSlow.y + 0.65 * (dFast.y - dSlow.y);
      const dEstZ = dSlow.z + 0.85 * (dFast.z - dSlow.z);

      const axDes = 5.2 * ex + 1.2 * tdx - 4.0 * vf.x + 2.2 * intPos.x + (drag / m0) * vf.x - dEstX;
      const azDes = 5.2 * ez + 1.2 * tdz - 4.0 * vf.z + 2.2 * intPos.z + (drag / m0) * vf.z - dEstZ;
      const ayDes = 6.2 * ey + 1.0 * tdy - 4.2 * vf.y + 2.6 * intPos.y + (drag / m0) * vf.y - dEstY;

      const ax = clamp(axDes, -4.2, 4.2);
      const az = clamp(azDes, -4.2, 4.2);
      const ay = clamp(ayDes, -4.0, 5.0);

      const totalAccY = Math.max(2.0, g + ay);
      const onPadFloor = obs.gateIndex === 3 && p.y <= 0.088 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.135 && padY < 0.06;
      const maxTilt = onPadFloor ? 0.11 : 0.48;

      const fwdAcc = cy * ax - sy * az;
      const rightAcc = sy * ax + cy * az;

      const pitch = clamp(Math.atan2(fwdAcc, totalAccY), -maxTilt, maxTilt);
      const roll = clamp(Math.atan2(-rightAcc, totalAccY), -maxTilt, maxTilt);

      const tiltFactor = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrust = clamp((m0 * (g + ay)) / (16 * tiltFactor), 0, 1);
      if (onPadFloor) thrust = Math.min(thrust, 0.25);
      lastThrust = thrust;

      const yawRate = clamp(-2.4 * att.yaw - 2.2 * intYaw - 0.15 * rates.yaw, -2, 2);
      return { thrust, roll, pitch, yawRate };
    },
  };
}

