      if (onPadFloor) thrust = Math.min(thrust, 0.20);
      lastThrust = thrust;

      const yawRate = clamp(-2.4 * att.yaw - 2.2 * intYaw - 0.15 * rates.yaw, -2, 2);
      return { thrust, roll, pitch, yawRate };
